steps.solution:
function countChecks(list, name) {
  let checks = 0
  for (const guest of list) {
    checks++
    if (guest === name) return checks
  }
  return checks
}

console.log(countChecks(['Ana', 'Luis', 'Maya'], 'Luis')) // 2
